# Detect if RestApi Body uses AWS::Include transform, which may reference parameters
# not visible to cfn-lint since the included file isn't loaded.
has_apigw_include = False
try:
    resources = cfn.template.get("Resources", {})
    if isinstance(resources, dict):
        for _, res in resources.items():
            if not isinstance(res, dict):
                continue
            if res.get("Type") != "AWS::ApiGateway::RestApi":
                continue
            props = res.get("Properties", {})
            if not isinstance(props, dict):
                continue
            body = props.get("Body")
            if isinstance(body, dict):
                transform = body.get("Fn::Transform")
                if isinstance(transform, dict):
                    if transform.get("Name") == "AWS::Include":
                        has_apigw_include = True
                        break
except Exception:  # pylint: disable=broad-except
    # If any unexpected structure, default to existing behavior
    has_apigw_include = False

for paramname in cfn.template.get("Parameters", {}).keys():
    if paramname not in refs:
        if paramname not in subs:
            # If the template includes an OpenAPI via AWS::Include, parameters may
            # be used inside the included spec. Avoid false positive W2001.
            if has_apigw_include:
                continue
            message = "Parameter {0} not used."
            matches.append(
                RuleMatch(["Parameters", paramname], message.format(paramname))
            )

return matches
